CREATE VIEW dbo.IV_Q$VENDA_MAQUINA_FY25 ( SeqPessoa, Pessoa, SeqQuestionario, SeqFormulario, Formulario, DtaRealizacao, UsuInclusao, DtaAlteracao, UsuAlteracao,  Observacao, SeqHistorico, Resultado, Processo, Departamento, LinkDocto, LinkNro, LinkSerie , PEDIDO_TIRADO_PARA, JD_QUOTE, TIPO_EQUIPAMENTO, MARCA_EQUIPAMENTO, MODELO_EQUIPAMENTO, QTDE_EQUIPAMENTOS, QTDE_PESO_DIANTEIRO, KG_PESO_DIANTEIRO, QTDE_PESO_TRASEIRO, KG_PESO_TRASEIRO, LASTRO_DIANTEIRO, LASTRO_TRASEIRO, RODADO_DIANTEIRO, RODADO_TRASEIRO, QTDE_VCR_PADRAO, QTDE_VCR_DELUXE, MEDIDA_BITOLA, CREEPER, INSTALACAO_CABINE_CA, AMS, RECEPTOR, ATIVACAO, MONITOR, VOLANTE, RADIO, CONECTIVIDADE, CONFIGURACAO_ADICION, VALOR_TOTAL, VALOR_SINAL, DATA_SINAL, VALOR_FINANCIADO, FORMA_PAGAMENTO, INSTITUICAO_FINANCEI, CONTATO_BANCO, CONFIGURACAO_AMS, COTACAO, FDD, CHASSI, PREPARACAO, PREVISAO_ENTREGA_PRE, DATA_ENTREGA, DESCONTO_INCONDICION, TRANSPORTADORA, VALOR_DO_FRETE)    AS SELECT TBASE.SEQPESSOA, TBASE.NOMERAZAO, QST.SEQQUESTIONARIO, FRM.SEQFORMULARIO, FRM.DESCRICAO, QST.DTAREALIZACAO, QST.USUINCLUSAO, QST.DTAALTERACAO, QST.USUALTERACAO, QST.OBS, QST.SEQHISTORICO, QST.RESULTADO, QST.PROCESSO, QST.DEPARTAMENTO, QST.LINKDOCTO, QST.LINKNRO, QST.LINKSERIE , TABF.PEDIDO_TIRADO_PARA, TABF.JD_QUOTE, TABF.TIPO_EQUIPAMENTO, TABF.MARCA_EQUIPAMENTO, TABF.MODELO_EQUIPAMENTO, TABF.QTDE_EQUIPAMENTOS, TABF.QTDE_PESO_DIANTEIRO, TABF.KG_PESO_DIANTEIRO, TABF.QTDE_PESO_TRASEIRO, TABF.KG_PESO_TRASEIRO, TABF.LASTRO_DIANTEIRO, TABF.LASTRO_TRASEIRO, TABF.RODADO_DIANTEIRO, TABF.RODADO_TRASEIRO, TABF.QTDE_VCR_PADRAO, TABF.QTDE_VCR_DELUXE, TABF.MEDIDA_BITOLA, TABF.CREEPER, TABF.INSTALACAO_CABINE_CA, TABF.AMS, TABF.RECEPTOR, TABF.ATIVACAO, TABF.MONITOR, TABF.VOLANTE, TABF.RADIO, TABF.CONECTIVIDADE, TABF.CONFIGURACAO_ADICION, TABF.VALOR_TOTAL, TABF.VALOR_SINAL, TABF.DATA_SINAL, TABF.VALOR_FINANCIADO, TABF.FORMA_PAGAMENTO, TABF.INSTITUICAO_FINANCEI, TABF.CONTATO_BANCO, TABF.CONFIGURACAO_AMS, TABF.COTACAO, TABF.FDD, TABF.CHASSI, TABF.PREPARACAO, TABF.PREVISAO_ENTREGA_PRE, TABF.DATA_ENTREGA, TABF.DESCONTO_INCONDICION, TABF.TRANSPORTADORA, TABF.VALOR_DO_FRETE   FROM IV_Q_VENDA_MAQUINA_FY25 TABF 	JOIN IV_QUESTIONARIO QST ON QST.SEQQUESTIONARIO =  TABF.SEQQUESTIONARIO 	JOIN IV_FORMULARIO FRM ON   FRM.SEQFORMULARIO = QST.SEQFORMULARIO 	JOIN GE_PESSOA TBASE ON TBASE.SEQPESSOA = QST.SEQPESSOA  